    "imageUrl": "https://imagens.ebc.com.br/3XM7OLYq_Vy0FhTCCDlLeg6U3Tk=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/21/limaterremoto.jpg?itok=oRILNhgj",
